"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["30702"],{29407(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.recorte_em_banca_de_recursos","status":422,"titulo":"A banca de an\xe1lise de recursos julga todos os recursos da fase e n\xe3o declara recorte de compet\xeancia"},"descricao":{"codigo":"uniplus.selecao.banca.recorte_em_banca_de_recursos","requisitos":["UNI-REQ-0398","UNI-REQ-0274"],"oQueAconteceu":["A banca de an\xe1lise de recursos foi declarada com recorte de compet\xeancia, isto \xe9,\\ncom a lista de categorias de documento que ela julga. A banca de an\xe1lise de\\nrecursos n\xe3o tem recorte: ela analisa o recurso da fase ou da etapa inteiro\\n(UNI-REQ-0274), e n\xe3o uma parte dele.","O recorte existe para distinguir duas bancas do mesmo tipo na mesma fase, cada\\numa com a sua parte da an\xe1lise documental, como descrito em\\n[Recorte de compet\xeancia obrigat\xf3rio](/erros/uniplus.selecao.banca_requerida.recorte_de_competencia_obrigatorio).\\nNa banca de recursos, um recorte deixaria parte do recurso sem quem o analise.","S\xf3 a banca da fase tem recorte de compet\xeancia: a recusa sai na grava\xe7\xe3o do\\ncronograma, no campo `fases[0].bancasRequeridas[0].categoriasDocumentoIds`, e\\nvem na lista `errors[]` da resposta.\\nA publica\xe7\xe3o e a retifica\xe7\xe3o em ato \xfanico conferem de novo."],"comoResolver":["Retire o recorte de compet\xeancia da banca de an\xe1lise de recursos. Se parte da\\nan\xe1lise documental precisa de bancas distintas, declare essas bancas com o tipo\\npr\xf3prio de cada uma, e mantenha uma \xfanica banca de an\xe1lise de recursos sem\\nrecorte.","O painel de conformidade aponta a pend\xeancia antes da publica\xe7\xe3o, no item\\n`cronograma_banca_de_recursos_sem_recorte`."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);